def _decode(name, payload, expected):
    raw = base64.b64decode(payload.encode("ascii"))
    digest = hashlib.sha256(raw).hexdigest()
    if digest != expected:
        raise ValueError(f"{name} does not match its embedded checksum")
    with np.load(io.BytesIO(raw), allow_pickle=False) as archive:
        return {key: archive[key].copy() for key in archive.files}


def members():
    """The two residual members as arrays, in the order the notebook used."""
    return [
        _decode("member_0.npz", MEMBER_0, MEMBER_0_SHA256),
        _decode("member_1.npz", MEMBER_1, MEMBER_1_SHA256),
    ]
